class Solution {
public:
    int maximizeGreatness(vector<int>& nums) {
        vector<int> t = nums;
        sort(t.begin(), t.end());
        sort(nums.begin(), nums.end());
        int i = 0;
        for (int x : nums)
            if (t[i] < x) i++;
        return i;
    }
};

