class Solution:
    def maximizeGreatness(self, nums: List[int]) -> int:
        from sortedcontainers import SortedList
        sl = SortedList(nums)
        ans = 0
        for x in nums:
            idx = sl.bisect_right(x)
            if idx < len(sl):
                sl.pop(idx)
                ans += 1
        return ans

