class Solution {
public:
    int maximizeGreatness(vector<int>& nums) {
        multiset<int> ms(nums.begin(), nums.end());
        int ans = 0;
        for (int x : nums) {
            auto it = ms.upper_bound(x);
            if (it != ms.end()) { ms.erase(it); ans++; }
        }
        return ans;
    }
};

