class Solution {
    public int maximizeGreatness(int[] nums) {
        TreeMap<Integer, Integer> ms = new TreeMap<>();
        for (int x : nums) ms.merge(x, 1, Integer::sum);
        int ans = 0;
        for (int x : nums) {
            Integer key = ms.higherKey(x);
            if (key != null) {
                if (ms.merge(key, -1, Integer::sum) == 0) ms.remove(key);
                ans++;
            }
        }
        return ans;
    }
}

