var maximizeGreatness = function(nums) {
    const arr = [...nums].sort((a, b) => a - b);
    let ans = 0;
    for (const x of nums) {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const m = (lo + hi) >> 1; if (arr[m] <= x) lo = m + 1; else hi = m; }
        if (lo < arr.length) { arr.splice(lo, 1); ans++; }
    }
    return ans;
};
